(11, '4', 'Ecuplatus-Wood-Box', 'Ecuplatus Wood Box', '6787a9081a88e_Frame 126 (3).webp,6787a9081a89d_Frame 128.webp', 'Ecuplatus Wood Box', 'Get high-quality Ecuplatus wood boxes from SKN Industries for secure and durable packaging. Ideal for shipping and storage. Explore our premium wooden packaging solutions today!', 'Durable Ecuplatus Wood Boxes – Strong & Reliable Packaging | SKN Industries', 'product-details-ecuplatus-wood-box', '2026-Jun-11', '<h4 style=\"-webkit-text-stroke-width: 0px; background-color: #ffffff; box-sizing: border-box; color: #212529; font-family: system-ui, -apple-system,;\">Product Description</h4>\r\n<p style=\"-webkit-text-stroke-width: 0px; background-color: #ffffff; box-sizing: border-box; color: #212529; font-family: system-ui, -apple-system,;\">With our dedication and sincerity, we have emerged as the foremost manufacturer and supplier of Ecuplatus Wood Box. This box is widely used in packaging industry for packing various goods. In order to ensure complete client satisfaction, we provide this box in various customized options in accordance with the clients\' requirements. The offered box is manufactured at our well-equipped manufacturing unit under the direction of our adroit professionals. Moreover, our patrons can avail this Ecuplatus Wood Box at market leading prices.</p>\r\n<h4 style=\"-webkit-text-stroke-width: 0px; background-color: #ffffff; box-sizing: border-box; color: #212529; font-family: system-ui, -apple-system,;\">Specification</h4>\r\n<p style=\"-webkit-text-stroke-width: 0px; background-color: #ffffff; box-sizing: border-box; color: #212529; font-family: system-ui, -apple-system,;\">Material : <span style=\"box-sizing: border-box; margin: 0px; padding: 0px;\">Wood</span></p>\r\n<p style=\"-webkit-text-stroke-width: 0px; background-color: #ffffff; box-sizing: border-box; color: #212529; font-family: system-ui, -apple-system,;\">Wood Type : <span style=\"box-sizing: border-box; margin: 0px; padding: 0px;\">Solid Wood</span></p>\r\n<p style=\"-webkit-text-stroke-width: 0px; background-color: #ffffff; box-sizing: border-box; color: #212529; font-family: system-ui, -apple-system,;\">Load Bearing Capacity : <span style=\"box-sizing: border-box; margin: 0px; padding: 0px;\">50-100 Kg</span></p>\r\n<p style=\"-webkit-text-stroke-width: 0px; background-color: #ffffff; box-sizing: border-box; color: #212529; font-family: system-ui, -apple-system,;\">Shape : <span style=\"box-sizing: border-box; margin: 0px; padding: 0px;\">Rectangular</span></p>\r\n<h4 style=\"-webkit-text-stroke-width: 0px; background-color: #ffffff; box-sizing: border-box; color: #212529; font-family: system-ui, -apple-system,;\">Key Features:</h4>\r\n<ul>\r\n<li style=\"box-sizing: border-box; margin: 0px; padding: 0px;\">Resistivity to termite attacks</li>\r\n<li style=\"box-sizing: border-box; margin: 0px; padding: 0px;\">Excellent strength</li>\r\n<li style=\"box-sizing: border-box; margin: 0px; padding: 0px;\">Long lasting</li>\r\n<li style=\"box-sizing: border-box; margin: 0px; padding: 0px;\">Easy handling</li>\r\n<li style=\"box-sizing: border-box; margin: 0px; padding: 0px;\">durable</li>\r\n<li style=\"box-sizing: border-box; margin: 0px; padding: 0px;\">Light Weight</li>\r\n<li style=\"box-sizing: border-box; margin: 0px; padding: 0px;\">Recyclable</li>\r\n<li style=\"box-sizing: border-box; margin: 0px; padding: 0px;\">Easy mobility</li>\r\n</ul>', '/ecuplatus-wood-box'),
(12, '4', 'Jumbo-Packaging-Boxes-with-Aluminium-Barrier-Foil-&-VCI-Packaging', 'Jumbo Packaging Boxes with Aluminium Barrier Foil', '6787a99403d1a_Frame 125 (3).webp,6787a99403d26_Frame 124 (3).webp,6787a99403d27_Frame 117 (6).webp', 'Jumbo Packaging Boxes with Aluminium Barrier Foil & VCI Packaging', 'Protect your goods with SKN Industries\' Jumbo Packaging Boxes featuring Aluminium Barrier Foil & VCI Packaging for superior moisture and corrosion resistance.', 'Durable Jumbo Packaging Boxes with Aluminium Barrier Foil & VCI – SKN Industries', 'product-details-jumbo-packaging-boxes-with-aluminium-barrier-foil-&-vci-packaging', '2026-Jun-11', '<h4 style=\"-webkit-text-stroke-width: 0px; background-color: #ffffff; box-sizing: border-box; color: #212529; font-family: system-ui, -apple-system,;\">Product Description</h4>\r\n<p style=\"-webkit-text-stroke-width: 0px; background-color: #ffffff; box-sizing: border-box; color: #212529; font-family: system-ui, -apple-system,;\">We have the expertise in big box packaging, these boxes are used in any big machine packaging. These boxes are designed and manufactured under our experts and rich quality of wood is used to ensure their durability and sturdiness and according to shipping or transportation process of the customer. We have branded and different VCI products like LD VCI bags, VCI papers, VCI Oils and Special Ermiters like VCI Chips which we provide our customers to ensure a rust free packaging.</p>\r\n<h4 style=\"-webkit-text-stroke-width: 0px; background-color: #ffffff; box-sizing: border-box; color: #212529; font-family: system-ui, -apple-system,;\">Key Features:</h4>\r\n<ul>\r\n<li style=\"box-sizing: border-box; margin: 0px; padding: 0px;\">Resistivity to termite attacks</li>\r\n<li style=\"box-sizing: border-box; margin: 0px; padding: 0px;\">Excellent strength</li>\r\n<li style=\"box-sizing: border-box; margin: 0px; padding: 0px;\">Long lasting</li>\r\n<li style=\"box-sizing: border-box; margin: 0px; padding: 0px;\">Easy handling</li>\r\n<li style=\"box-sizing: border-box; margin: 0px; padding: 0px;\">durable</li>\r\n<li style=\"box-sizing: border-box; margin: 0px; padding: 0px;\">Light Weight</li>\r\n<li style=\"box-sizing: border-box; margin: 0px; padding: 0px;\">Recyclable</li>\r\n<li style=\"box-sizing: border-box; margin: 0px; padding: 0px;\">Easy mobility</li>\r\n</ul>', '/jumbo-packaging-boxes-with-aluminium-barrier-foil-&-vci-packaging'),
(13, '5', 'On-Site-Container-Packing', 'On Site Container Packing', '678a1d8096611_images.webp,678a1d8096619_On-Site-Packaging-Services.webp', 'On-Site Container Packing Service', 'SKN Industries offers On-Site Container Packing for safe, efficient, and professional cargo handling. Ensure secure packaging for shipments. Contact us today!', 'On-Site Container Packing Services | Secure & Efficient Packing – SKN Industries', 'product-details-on-site-container-packing', '2026-Jun-11', '<h4 style=\"-webkit-text-stroke-width: 0px; background-color: #ffffff; box-sizing: border-box; color: #212529; font-family: system-ui, -apple-system,;\">Product Description</h4>\r\n<p style=\"-webkit-text-stroke-width: 0px; background-color: #ffffff; box-sizing: border-box; color: #212529; font-family: system-ui, -apple-system,;\">Since our inception, we are indulged in providing the finest quality On Site Packaging Services to our valuable patrons. We have an enthusiastic team for onsite packaging development who hold years of expertise in their field. We evaluate the requirements of customer working conditions, dispatch destinations and accordingly provide the samples and after getting approvals we supply total materials on daily basis in various customized options. We keep the inventory as per the transmit schedule of our customers and pack the materials on the customer site under the supervision of our professionals. Further, our valuable clients can easily avail these On Site Packaging Services at market leading prices.</p>\r\n<h4 style=\"-webkit-text-stroke-width: 0px; background-color: #ffffff; box-sizing: border-box; color: #212529; font-family: system-ui, -apple-system,;\">Specification</h4>\r\n<p style=\"-webkit-text-stroke-width: 0px; background-color: #ffffff; box-sizing: border-box; color: #212529; font-family: system-ui, -apple-system,;\">Duration : <span style=\"box-sizing: border-box; margin: 0px; padding: 0px;\">1-3 Days</span></p>\r\n<p style=\"-webkit-text-stroke-width: 0px; background-color: #ffffff; box-sizing: border-box; color: #212529; font-family: system-ui, -apple-system,;\">Location : <span style=\"box-sizing: border-box; margin: 0px; padding: 0px;\">Noida NCR</span></p>\r\n<p style=\"-webkit-text-stroke-width: 0px; background-color: #ffffff; box-sizing: border-box; color: #212529; font-family: system-ui, -apple-system,;\">Service Mode : <span style=\"box-sizing: border-box; margin: 0px; padding: 0px;\">Offline</span></p>\r\n<p style=\"-webkit-text-stroke-width: 0px; background-color: #ffffff; box-sizing: border-box; color: #212529; font-family: system-ui, -apple-system,;\">Service Type : <span style=\"box-sizing: border-box; margin: 0px; padding: 0px;\">Onsite Packaging</span></p>\r\n<h4 style=\"-webkit-text-stroke-width: 0px; background-color: #ffffff; box-sizing: border-box; color: #212529; font-family: system-ui, -apple-system,;\">Lashing Straps/ Buckels / Hooks</h4>\r\n<p style=\"-webkit-text-stroke-width: 0px; background-color: #ffffff; box-sizing: border-box; color: #212529; font-family: system-ui, -apple-system,;\">Some of the important parts required in tying loads inside site containers during shipment or storage include lashing straps, buckles, and hooks. Lashing straps are made of robust belts of different materials such as polyester or nylon with reinforced strength to handle heavy loads. These straps have buckles through which they are threaded. After threading through the buckles, they can then get tightened for their correct tension, thus keeping down loads firmly on the container. Buckles could either be cam buckles or ratchet buckles. While ratchet buckles offer more tension for heavier loads, the cam buckles do not offer much in terms of a higher pulling effort. Hooks are usually at the end of lashing straps so that they can be fastened at the points where one wishes in a container. The buckles and straps fixed on the hooks prevent the shifting of cargo in the moving truck and further damaging it by shattering it into pieces, particularly when bad weather exists. Lashing systems play a great role in securing loads such as machinery, autos, or heavy shipments to ensure safety and meet shipping requirements.</p>', '/on-site-container-packing'),
(14, '5', 'Container-Packaging-Services', 'Container Packaging Services', '694f8cbab3c34_images.webp', 'Container Packaging Services', 'Ensure safe and efficient cargo shipping with SKN Industries\' container packaging services. Designed for maximum protection and durability. Explore our solutions today!', 'Reliable Container Packaging Services – Secure & Efficient | SKN Industries', 'product-details-container-packaging-services', '2026-Jun-11', '<h4 style=\"-webkit-text-stroke-width: 0px; background-color: #ffffff; box-sizing: border-box; color: #212529; font-family: system-ui, -apple-system,;\">Product Description</h4>\r\n<p style=\"-webkit-text-stroke-width: 0px; background-color: #ffffff; box-sizing: border-box; color: #212529; font-family: system-ui, -apple-system,;\">Fostered with immense years of industry experience and market understanding, we are offering high quality Container Packaging Services to our valuable customers. We have a team of skilled professionals who are well-experienced in their field and provide these packaging services on timely manner as desired by the customers. We render these services in various customized options to different kinds of customers like automobile pharmaceutical, FMCG, Textile, beverages and more. Using the advanced packaging materials and equipments, we offer these Container Packaging Services at nominal price.</p>\r\n<h4 style=\"-webkit-text-stroke-width: 0px; background-color: #ffffff; box-sizing: border-box; color: #212529; font-family: system-ui, -apple-system,;\">Specification</h4>\r\n<p style=\"-webkit-text-stroke-width: 0px; background-color: #ffffff; box-sizing: border-box; color: #212529; font-family: system-ui, -apple-system,;\">Duration : <span style=\"box-sizing: border-box; margin: 0px; padding: 0px;\">1-3 Days</span></p>\r\n<p style=\"-webkit-text-stroke-width: 0px; background-color: #ffffff; box-sizing: border-box; color: #212529; font-family: system-ui, -apple-system,;\">Location : <span style=\"box-sizing: border-box; margin: 0px; padding: 0px;\">Noida NCR</span></p>\r\n<p style=\"-webkit-text-stroke-width: 0px; background-color: #ffffff; box-sizing: border-box; color: #212529; font-family: system-ui, -apple-system,;\">Service Mode : <span style=\"box-sizing: border-box; margin: 0px; padding: 0px;\">Offline</span></p>\r\n<p style=\"-webkit-text-stroke-width: 0px; background-color: #ffffff; box-sizing: border-box; color: #212529; font-family: system-ui, -apple-system,;\">Service Type : <span style=\"box-sizing: border-box; margin: 0px; padding: 0px;\">Container Packaging</span></p>', '/container-packaging-services'),
(15, '11', 'PVC-(Polyvinyl-Chloride)-Shrink-Film', 'PVC (Polyvinyl Chloride) Shrink Film', '678a1e69afc77_Frame 131 (6).webp', 'PVC (Polyvinyl Chloride) Shrink Film', 'Buy PVC (Polyvinyl Chloride) Shrink Film from SKN Industries for durable, flexible, and secure packaging solutions. Ideal for industrial & commercial use. Order now!', ' High-Quality PVC (Polyvinyl Chloride) Shrink Film | SKN Industries', 'product-details-pvc-(polyvinyl-chloride)-shrink-film', '2026-Jun-11', '<h4 style=\"-webkit-text-stroke-width: 0px; background-color: #ffffff; box-sizing: border-box; color: #212529; font-family: system-ui, -apple-system,;\">Product Description</h4>\r\n<p style=\"-webkit-text-stroke-width: 0px; background-color: #ffffff; box-sizing: border-box; color: #212529; font-family: system-ui, -apple-system,;\">PVC (Polyvinyl Chloride) Shrink Film is a common shrink wrap material known for its clarity, durability, and low cost. It shrinks at low temperatures and is easy to seal, making it suitable for packaging a variety of products like CDs, DVDs, software, and small boxes. However, it releases hydrogen chloride gas when heated, so adequate ventilation is necessary during the shrinking process. used for food and beverages mostly.</p>', '/pvc-(polyvinyl-chloride)-shrink-film'),
(16, '11', 'LD-Shrink-Film', 'LD Shrink Film', '678a1ed9ccf74_Frame 130 (9).webp', 'LD Shrink Film', 'Buy premium LD Shrink Film from SKN Industries for secure, durable, and flexible packaging. Ideal for industrial & commercial use. Order high-quality shrink film today!', ' LD Shrink Film | Durable & Flexible Packaging – SKN Industries', 'product-details-ld-shrink-film', '2026-Jun-11', '<h4 style=\"-webkit-text-stroke-width: 0px; background-color: #ffffff; box-sizing: border-box; color: #212529; font-family: system-ui, -apple-system,;\">Product Description</h4>\r\n<p style=\"-webkit-text-stroke-width: 0px; background-color: #ffffff; box-sizing: border-box; color: #212529; font-family: system-ui, -apple-system,;\">LD Shrink Film refers to Low-Density Polyethylene (LDPE) Shrink Film. It is thicker and more resilient than other shrink films, offering excellent strength and puncture resistance. LDPE shrink film is ideal for bundling heavier items, wrapping pallets, and securing multipacks of products like Waterbottles. It requires higher temperatures to shrink and is commonly used in industrial applications where durability is essential.</p>', '/ld-shrink-film'),
(17, '11', 'POF-(Polyolefin)-Shrink-Film', 'POF (Polyolefin) Shrink Film', '678a1f136ed52_Frame 129 (6).webp', 'POF (Polyolefin) Shrink Film', 'Get premium POF (Polyolefin) Shrink Film from SKN Industries for strong, flexible, and eco-friendly packaging. Ideal for various industries. Order high-quality shrink film now!', 'POF (Polyolefin) Shrink Film | Durable Packaging – SKN Industries', 'product-details-pof-(polyolefin)-shrink-film', '2026-Jun-11', '<h4 style=\"-webkit-text-stroke-width: 0px; background-color: #ffffff; box-sizing: border-box; color: #212529; font-family: system-ui, -apple-system,;\">Product Description</h4>\r\n<p style=\"-webkit-text-stroke-width: 0px; background-color: #ffffff; box-sizing: border-box; color: #212529; font-family: system-ui, -apple-system,;\">POF (Polyolefin) Shrink Film is a high-quality shrink wrap made from polyolefin polymers. It is favored for its clarity, strength, and versatility. POF shrink film is FDA-approved for direct food contact, making it suitable for packaging food items, cosmetics, and pharmaceuticals. It doesn\'t emit harmful fumes during processing, making it more environmentally friendly and safer for workers. The film is flexible, has excellent seal strength, and maintains its integrity over a wide temperature range.</p>', '/pof-(polyolefin)-shrink-film'),
(18, '12', 'Pneumatic-PET-Strapping-Tool', 'Pneumatic PET Strapping Tool', '678a230d3097e_pet tool.webp,678a230d3098f_pet strap tool.webp', 'Pneumatic PET Strapping Tool', ' Get the best Pneumatic PET Strapping Tool from SKN Industries for strong, efficient, and reliable packaging. Explore our high-quality solutions today!', 'Premium Pneumatic PET Strapping Tool – SKN Industries for Secure Packaging', 'product-details-pneumatic-pet-strapping-tool', '2026-Jun-11', '<h4 style=\"-webkit-text-stroke-width: 0px; background-color: #ffffff; box-sizing: border-box; color: #212529; font-family: system-ui, -apple-system,;\">Pneumatic PET Strapping Tool Price And Quantity</h4>\r\n<p style=\"-webkit-text-stroke-width: 0px; background-color: #ffffff; box-sizing: border-box; color: #212529; font-family: system-ui, -apple-system,;\">Minimum Order Quantity : <span style=\"box-sizing: border-box; margin: 0px; padding: 0px;\">1</span></p>\r\n<p style=\"-webkit-text-stroke-width: 0px; background-color: #ffffff; box-sizing: border-box; color: #212529; font-family: system-ui, -apple-system,;\">Unit Price : <span style=\"box-sizing: border-box; margin: 0px; padding: 0px;\">25000 INR</span></p>\r\n<h4 style=\"-webkit-text-stroke-width: 0px; background-color: #ffffff; box-sizing: border-box; color: #212529; font-family: system-ui, -apple-system,;\">Product Description</h4>\r\n<p style=\"-webkit-text-stroke-width: 0px; background-color: #ffffff; box-sizing: border-box; color: #212529; font-family: system-ui, -apple-system,;\">We put forward a broad range of Pneumatic Strapping Tool that is manufactured in adherence with the set industry standards using advanced technology. Only the best quality components are used in the manufacturing of this strapping tool for ensuring that the efficiency is maximized and a superior grade machine is delivered to the clients. Our offered tool is widely used for packages and pallets. Further, we are providing this Pneumatic Strapping Tool at the most affordable price to our valuable clients.</p>\r\n<h4 style=\"-webkit-text-stroke-width: 0px; background-color: #ffffff; box-sizing: border-box; color: #212529; font-family: system-ui, -apple-system,;\">Specification</h4>\r\n<p style=\"-webkit-text-stroke-width: 0px; background-color: #ffffff; box-sizing: border-box; color: #212529; font-family: system-ui, -apple-system,;\">PET Strap Thickness : <span style=\"box-sizing: border-box; margin: 0px; padding: 0px;\">0.5 - 1.2 mm</span></p>\r\n<p style=\"-webkit-text-stroke-width: 0px; background-color: #ffffff; box-sizing: border-box; color: #212529; font-family: system-ui, -apple-system,;\">PET Strap Width : <span style=\"box-sizing: border-box; margin: 0px; padding: 0px;\">19 - 25 mm</span></p>\r\n<p style=\"-webkit-text-stroke-width: 0px; background-color: #ffffff; box-sizing: border-box; color: #212529; font-family: system-ui, -apple-system,;\">PET Strap Material : <span style=\"box-sizing: border-box; margin: 0px; padding: 0px;\">Polyester</span></p>\r\n<p style=\"-webkit-text-stroke-width: 0px; background-color: #ffffff; box-sizing: border-box; color: #212529; font-family: system-ui, -apple-system,;\">Tool Size : <span style=\"box-sizing: border-box; margin: 0px; padding: 0px;\">280x160x180 mm</span></p>\r\n<p style=\"-webkit-text-stroke-width: 0px; background-color: #ffffff; box-sizing: border-box; color: #212529; font-family: system-ui, -apple-system,;\">Tool Weight : <span style=\"box-sizing: border-box; margin: 0px; padding: 0px;\">3.8 kg</span></p>\r\n<p style=\"-webkit-text-stroke-width: 0px; background-color: #ffffff; box-sizing: border-box; color: #212529; font-family: system-ui, -apple-system,;\">Tension : <span style=\"box-sizing: border-box; margin: 0px; padding: 0px;\">3000 N</span></p>\r\n<p style=\"-webkit-text-stroke-width: 0px; background-color: #ffffff; box-sizing: border-box; color: #212529; font-family: system-ui, -apple-system,;\">Air Pressure : <span style=\"box-sizing: border-box; margin: 0px; padding: 0px;\">0.5-0.8 MPa(72-100PSI)</span></p>\r\n<p style=\"-webkit-text-stroke-width: 0px; background-color: #ffffff; box-sizing: border-box; color: #212529; font-family: system-ui, -apple-system,;\">Strap Width : <span style=\"box-sizing: border-box; margin: 0px; padding: 0px;\">19-25 mm</span></p>\r\n<h4 style=\"-webkit-text-stroke-width: 0px; background-color: #ffffff; box-sizing: border-box; color: #212529; font-family: system-ui, -apple-system,;\">Major Key Features:</h4>\r\n<ul>\r\n<li style=\"box-sizing: border-box; margin: 0px; padding: 0px;\">Easy Installation</li>\r\n<li style=\"box-sizing: border-box; margin: 0px; padding: 0px;\">Less maintenance</li>\r\n<li style=\"box-sizing: border-box; margin: 0px; padding: 0px;\">Eay to use</li>\r\n<li style=\"box-sizing: border-box; margin: 0px; padding: 0px;\">Long service life</li>\r\n</ul>', '/pneumatic-pet-strapping-tool'),
(19, '12', 'Compressed-Strap-Air-Tools', 'Compressed Strap Air Tools', '678a234a5f693_strap-1.webp', 'Compressed Strap Air Tools', 'Get high-quality compressed strap air tools from SKN Industries for secure and efficient strapping. Ideal for industrial packaging needs. Explore our reliable tools today!', 'Premium Compressed Strap Air Tools – Durable & Efficient | SKN Industries', 'product-details-compressed-strap-air-tools', '2026-Jun-11', '<h4 style=\"-webkit-text-stroke-width: 0px; background-color: #ffffff; box-sizing: border-box; color: #212529; font-family: system-ui, -apple-system,;\">Product Description</h4>\r\n<p style=\"-webkit-text-stroke-width: 0px; background-color: #ffffff; box-sizing: border-box; color: #212529; font-family: system-ui, -apple-system,;\">Owing to our rich industry experience, we are engrossed in offering the premium quality Compressed Air Tools. Offered range of tools is manufactured using standard quality of raw materials with the aid of advanced machineries. These tools are widely used for various industrial applications that require compressing air. These tools are thoroughly examined on various parameters of quality to ensure their defect-free nature. Furthermore, offered Compressed Air Tools can be availed from us at market-competitive prices.</p>\r\n<h4 style=\"-webkit-text-stroke-width: 0px; background-color: #ffffff; box-sizing: border-box; color: #212529; font-family: system-ui, -apple-system,;\">Key Features:</h4>\r\n<ul>\r\n<li style=\"box-sizing: border-box; margin: 0px; padding: 0px;\">Long lasting</li>\r\n<li style=\"box-sizing: border-box; margin: 0px; padding: 0px;\">Easy to use</li>\r\n<li style=\"box-sizing: border-box; margin: 0px; padding: 0px;\">Recyclable</li>\r\n<li style=\"box-sizing: border-box; margin: 0px; padding: 0px;\">Corrosion resistance</li>\r\n<li style=\"box-sizing: border-box; margin: 0px; padding: 0px;\">less maintenance</li>\r\n</ul>', '/compressed-strap-air-tools'),
(20, '13', 'Angle-Board', 'Angle Board', '678a23b276d82_Frame 129 (5).webp', 'Angle Boards', 'Protect shipments with durable angle boards from SKN Industries. Ideal for securing pallet edges and preventing damage during transit. Explore our edge protection solutions today!', 'High-Quality Angle Boards – Strong Edge Protection | SKN Industries', 'product-details-angle-board', '2026-Jun-11', '<h4 style=\"-webkit-text-stroke-width: 0px; background-color: #ffffff; box-sizing: border-box; color: #212529; font-family: system-ui, -apple-system,;\">Product Description</h4>\r\n<p style=\"-webkit-text-stroke-width: 0px; background-color: #ffffff; box-sizing: border-box; color: #212529; font-family: system-ui, -apple-system,;\">With our constant efforts and domain expertise, we have emerged as one of the fast growing manufacturers and suppliers of excellent quality Angle Board. Offered board finds wide application in packaging industry as cardboard edge protectors. It is manufactured at our state-of-the-art manufacturing unit by utilizing the excellent quality raw materials and the advanced technique in line with the set standards of quality. Further, we are offering this Angle Board at the market leading prices.&nbsp;</p>\r\n<h4 style=\"-webkit-text-stroke-width: 0px; background-color: #ffffff; box-sizing: border-box; color: #212529; font-family: system-ui, -apple-system,;\">Product Features:</h4>\r\n<ul>\r\n<li style=\"box-sizing: border-box; margin: 0px; padding: 0px;\">Smooth finish</li>\r\n<li style=\"box-sizing: border-box; margin: 0px; padding: 0px;\">Light weight</li>\r\n<li style=\"box-sizing: border-box; margin: 0px; padding: 0px;\">Durability</li>\r\n<li style=\"box-sizing: border-box; margin: 0px; padding: 0px;\">Re-usable</li>\r\n<li style=\"box-sizing: border-box; margin: 0px; padding: 0px;\">Less maintenance</li>\r\n<li style=\"box-sizing: border-box; margin: 0px; padding: 0px;\">Easy to fit</li>\r\n</ul>', '/angle-board');
INSERT INTO `product` (`proid`, `catid`, `product_name`, `product_url`, `image1`, `metakeyword`, `metadescription`, `metatitle`, `canonical_url`, `date`, `description`, `slug_url`) VALUES
(21, '13', 'Angle-Edge-Board', 'Angle Edge Board', '678a2401a8dfe_angle.webp', ' Angle Edge Boards', 'Get high-quality angle edge boards from SKN Industries for strong edge protection in packaging and shipping. Prevent damage and ensure safety. Explore our solutions today!', 'Durable Angle Edge Boards – Superior Protection | SKN Industries', 'product-details-angle-edge-board', '2026-Jun-11', '<h4 style=\"-webkit-text-stroke-width: 0px; background-color: #ffffff; box-sizing: border-box; color: #212529; font-family: system-ui, -apple-system,;\">Product Description</h4>\r\n<p style=\"-webkit-text-stroke-width: 0px; background-color: #ffffff; box-sizing: border-box; color: #212529; font-family: system-ui, -apple-system,;\">Utilizing the most modern technology and advanced machinery, we bring forth the wide array of Angle Edge Board for our esteemed clients. This board is mainly used as a protection for packaging products for their safe transit. This board is manufactured using the best grade raw materials and the innovative technology in accordance with the set norms of quality. Moreover, our patrons can avail this Angle Edge Board at industry leading rates.</p>\r\n<h4 style=\"-webkit-text-stroke-width: 0px; background-color: #ffffff; box-sizing: border-box; color: #212529; font-family: system-ui, -apple-system,;\">Specification</h4>\r\n<p style=\"-webkit-text-stroke-width: 0px; background-color: #ffffff; box-sizing: border-box; color: #212529; font-family: system-ui, -apple-system,;\">Length : <span style=\"box-sizing: border-box; margin: 0px; padding: 0px;\">2-5 Feet</span></p>\r\n<p style=\"-webkit-text-stroke-width: 0px; background-color: #ffffff; box-sizing: border-box; color: #212529; font-family: system-ui, -apple-system,;\">Material : <span style=\"box-sizing: border-box; margin: 0px; padding: 0px;\">Kraft Paper</span></p>\r\n<p style=\"-webkit-text-stroke-width: 0px; background-color: #ffffff; box-sizing: border-box; color: #212529; font-family: system-ui, -apple-system,;\">Thickness : <span style=\"box-sizing: border-box; margin: 0px; padding: 0px;\">1.5-10 mm</span></p>\r\n<p style=\"-webkit-text-stroke-width: 0px; background-color: #ffffff; box-sizing: border-box; color: #212529; font-family: system-ui, -apple-system,;\">Usage : <span style=\"box-sizing: border-box; margin: 0px; padding: 0px;\">Packaging Industry</span></p>\r\n<p style=\"-webkit-text-stroke-width: 0px; background-color: #ffffff; box-sizing: border-box; color: #212529; font-family: system-ui, -apple-system,;\">Width : <span style=\"box-sizing: border-box; margin: 0px; padding: 0px;\">30-85 mm</span></p>\r\n<h4 style=\"-webkit-text-stroke-width: 0px; background-color: #ffffff; box-sizing: border-box; color: #212529; font-family: system-ui, -apple-system,;\">Product Features:</h4>\r\n<ul>\r\n<li style=\"box-sizing: border-box; margin: 0px; padding: 0px;\">Smooth finish</li>\r\n<li style=\"box-sizing: border-box; margin: 0px; padding: 0px;\">Light weight</li>\r\n<li style=\"box-sizing: border-box; margin: 0px; padding: 0px;\">Easy to deflate</li>\r\n<li style=\"box-sizing: border-box; margin: 0px; padding: 0px;\">Re-usable</li>\r\n<li style=\"box-sizing: border-box; margin: 0px; padding: 0px;\">High strength</li>\r\n</ul>', '/angle-edge-board'),
(22, '13', 'EPE-Foam-Roll', 'EPE Foam Roll', '678a2646bbcb4_Frame 130 (4).webp', ' EPE Foam Rolls', 'Get durable EPE foam rolls from SKN Industries for excellent shock absorption and protective packaging. Ideal for various industries. Explore our foam solutions today!', ' High-Quality EPE Foam Rolls – Superior Cushioning | SKN Industries', 'product-details-epe-foam-roll', '2026-Jun-11', '<h4 style=\"-webkit-text-stroke-width: 0px; background-color: #ffffff; box-sizing: border-box; color: #212529; font-family: system-ui, -apple-system,;\">Product Description</h4>\r\n<p style=\"-webkit-text-stroke-width: 0px; background-color: #ffffff; box-sizing: border-box; color: #212529; font-family: system-ui, -apple-system,;\">We are counted amongst the leading manufacturers and suppliers of excellent quality EPE Foam Roll which is widely used for safe packing of various kinds of products. The offered roll is manufactured at our technologically advanced production unit under the supervision of highly skilled professionals using the best quality EPE material and the advanced technology. Moreover, this EPE Foam Roll is offered at industry leading rates to our valuable clients.</p>\r\n<h4 style=\"-webkit-text-stroke-width: 0px; background-color: #ffffff; box-sizing: border-box; color: #212529; font-family: system-ui, -apple-system,;\">Specification</h4>\r\n<p style=\"-webkit-text-stroke-width: 0px; background-color: #ffffff; box-sizing: border-box; color: #212529; font-family: system-ui, -apple-system,;\">Density : <span style=\"box-sizing: border-box; margin: 0px; padding: 0px;\">20-25kgs/m3</span></p>\r\n<p style=\"-webkit-text-stroke-width: 0px; background-color: #ffffff; box-sizing: border-box; color: #212529; font-family: system-ui, -apple-system,;\">Length : <span style=\"box-sizing: border-box; margin: 0px; padding: 0px;\">10-20 m</span></p>\r\n<p style=\"-webkit-text-stroke-width: 0px; background-color: #ffffff; box-sizing: border-box; color: #212529; font-family: system-ui, -apple-system,;\">Material : <span style=\"box-sizing: border-box; margin: 0px; padding: 0px;\">EPE</span></p>\r\n<p style=\"-webkit-text-stroke-width: 0px; background-color: #ffffff; box-sizing: border-box; color: #212529; font-family: system-ui, -apple-system,;\">Thickness : <span style=\"box-sizing: border-box; margin: 0px; padding: 0px;\">2 to 3 mm</span></p>\r\n<p style=\"-webkit-text-stroke-width: 0px; background-color: #ffffff; box-sizing: border-box; color: #212529; font-family: system-ui, -apple-system,;\">Width : <span style=\"box-sizing: border-box; margin: 0px; padding: 0px;\">1-1.5m</span></p>\r\n<h4 style=\"-webkit-text-stroke-width: 0px; background-color: #ffffff; box-sizing: border-box; color: #212529; font-family: system-ui, -apple-system,;\">Product Features:</h4>\r\n<ul>\r\n<li style=\"box-sizing: border-box; margin: 0px; padding: 0px;\">Smooth finish</li>\r\n<li style=\"box-sizing: border-box; margin: 0px; padding: 0px;\">Light weight</li>\r\n<li style=\"box-sizing: border-box; margin: 0px; padding: 0px;\">Smooth Surface</li>\r\n<li style=\"box-sizing: border-box; margin: 0px; padding: 0px;\">Re-usable</li>\r\n</ul>', '/epe-foam-roll'),
(23, '13', 'Dunnage-Air-Bags', 'Dunnage Air Bags', '678a267b47015_Frame 131 (2).webp', 'Durable Dunnage Air Bags', 'Protect shipments with high-quality dunnage air bags from SKN Industries. Ideal for cargo stabilization and damage prevention. Explore our reliable packaging solutions today!', 'Durable Dunnage Air Bags – Secure Cargo Protection | SKN Industries', 'product-details-dunnage-air-bags', '2026-Jun-11', '<h4 style=\"-webkit-text-stroke-width: 0px; background-color: #ffffff; box-sizing: border-box; color: #212529; font-family: system-ui, -apple-system,;\">Product Description</h4>\r\n<p style=\"-webkit-text-stroke-width: 0px; background-color: #ffffff; box-sizing: border-box; color: #212529; font-family: system-ui, -apple-system,;\">Dunnage air bags are inflatable bags used to secure and stabilize cargo during transportation. Placed between pallets, boxes, or containers, they fill voids and prevent movement, protecting goods from damage caused by shifting during transit. Made from materials like plastic, paper, or woven polypropylene, dunnage air bags are lightweight, reusable, and easy to inflate using air compressors. They are commonly used in shipping by truck, rail, or sea to cushion and secure loads, ensuring safe delivery of fragile or heavy items.<br>Our range of Dunnage Air Bags are widely used in packaging industry for a secure transit of various packaging items. These bags are manufactured by making use of top quality raw materials under the strict supervision of our highly skilled professionals by employing the latest machineries. Offered bags are thoroughly checked on various parameters of quality to ensure their defect free nature. Further, our esteemed patrons can avail these Dunnage Air Bags at market leading prices.</p>\r\n<h4 style=\"-webkit-text-stroke-width: 0px; background-color: #ffffff; box-sizing: border-box; color: #212529; font-family: system-ui, -apple-system,;\">Specification</h4>\r\n<p style=\"-webkit-text-stroke-width: 0px; background-color: #ffffff; box-sizing: border-box; color: #212529; font-family: system-ui, -apple-system,;\">Dimensions : <span style=\"box-sizing: border-box; margin: 0px; padding: 0px;\">Up to 1000 x 2200 mm</span></p>\r\n<p style=\"-webkit-text-stroke-width: 0px; background-color: #ffffff; box-sizing: border-box; color: #212529; font-family: system-ui, -apple-system,;\">Inner Material : <span style=\"box-sizing: border-box; margin: 0px; padding: 0px;\">PA Film</span></p>\r\n<p style=\"-webkit-text-stroke-width: 0px; background-color: #ffffff; box-sizing: border-box; color: #212529; font-family: system-ui, -apple-system,;\">Max void : <span style=\"box-sizing: border-box; margin: 0px; padding: 0px;\">Up to 20cm</span></p>\r\n<p style=\"-webkit-text-stroke-width: 0px; background-color: #ffffff; box-sizing: border-box; color: #212529; font-family: system-ui, -apple-system,;\">Load Weight : <span style=\"box-sizing: border-box; margin: 0px; padding: 0px;\">1-2 Ton</span></p>\r\n<p style=\"-webkit-text-stroke-width: 0px; background-color: #ffffff; box-sizing: border-box; color: #212529; font-family: system-ui, -apple-system,;\">Material : <span style=\"box-sizing: border-box; margin: 0px; padding: 0px;\">PVC and Paper</span></p>\r\n<h4 style=\"-webkit-text-stroke-width: 0px; background-color: #ffffff; box-sizing: border-box; color: #212529; font-family: system-ui, -apple-system,;\">Product Features:</h4>\r\n<ul>\r\n<li style=\"box-sizing: border-box; margin: 0px; padding: 0px;\">Smooth finish</li>\r\n<li style=\"box-sizing: border-box; margin: 0px; padding: 0px;\">Light weight</li>\r\n<li style=\"box-sizing: border-box; margin: 0px; padding: 0px;\">Easy to deflate</li>\r\n<li style=\"box-sizing: border-box; margin: 0px; padding: 0px;\">Re-usable</li>\r\n</ul>', '/dunnage-air-bags'),
(24, '15', 'Transparent-Bopp-Tape', 'Transparent Bopp Tape', '678a26c509f91_Frame 117 (7).webp', 'Transparent Bopp Tape', 'Get premium Transparent BOPP Tape from SKN Industries for strong adhesion, durability, and secure packaging. Ideal for industrial & commercial use. Order now!', 'High-Quality Transparent BOPP Tape | Strong Adhesive Tape – SKN Industries', 'product-details-transparent-bopp-tape', '2026-Jun-11', '<h4 style=\"-webkit-text-stroke-width: 0px; background-color: #ffffff; box-sizing: border-box; color: #212529; font-family: system-ui, -apple-system,;\">Product Description</h4>\r\n<p style=\"-webkit-text-stroke-width: 0px; background-color: #ffffff; box-sizing: border-box; color: #212529; font-family: system-ui, -apple-system,;\">Transparent tapes are transparent adhesive tapes commonly used in packaging, sealing, and any other day-to-day activity like gift packaging and labeling. They are made from BOPP, cellulose film, etc. The materials have strong adhesion and durability, nearly becoming invisible on surfaces. The transparent tapes are used both in offices, homes, and industries due to their practicality, usability, and neat appearance. The tapes are available in widths and bonding strengths to suit the flexibility required by very different applications-from general-purpose usage to high-end packaging products.</p>', '/transparent-bopp-tape'),
(25, '15', 'Brown-Bopp-Tape', 'Brown Bopp Tape', '678a26fbbbbc3_Frame 129 (4).webp', 'Brown BOPP Tape', 'Shop durable brown BOPP tape from SKN Industries for secure packaging and sealing. Perfect for industrial and commercial use. Explore our premium tape solutions today!', 'High-Quality Brown BOPP Tape – Strong & Reliable | SKN Industries', 'product-details-brown-bopp-tape', '2026-Jun-11', '<h4 style=\"-webkit-text-stroke-width: 0px; background-color: #ffffff; box-sizing: border-box; color: #212529; font-family: system-ui, -apple-system,;\">Product Description</h4>\r\n<p style=\"-webkit-text-stroke-width: 0px; background-color: #ffffff; box-sizing: border-box; color: #212529; font-family: system-ui, -apple-system,;\">Brown BOPP tapes are tapes made of Biaxially Oriented Polypropylene (BOPP) film with its color being brown on the back. They are highly used for packaging purposes where they seal large cardboard boxes and cartons. The color will give a neat appearance and professional look especially if used on colored or kraft paper to box cartons. Brown BOPP tapes have high adhesion, durability, and resistance to moisture and tear, and are made for both heavy duty and light-duty applications. It is used mainly in logistics, shipping, and warehousing.</p>', '/brown-bopp-tape');

